With WeekdayFoodCustomers AS (SELECT DISTINCT c.Id, c.FirstName, c.LastName FROM receipts r JOIN customers c ON r.CustomerId = c.Id JOIN items i ON r.ReceiptNumber = i.Receipt JOIN goods g ON i.Item = g.Id WHERE g.Food IS NOT NULL AND CASE CAST(SUBSTR(r.Date, 1, 2) AS INTEGER) % 7 WHEN 1 THEN 'Monday' WHEN 2 THEN 'Tuesday' WHEN 3 THEN 'Wednesday' WHEN 4 THEN 'Thursday' WHEN 5 THEN 'Friday' ELSE 'Weekend' END NOT IN ('Saturday', 'Sunday')),

SpendingPatterns AS (SELECT wfc.Id, AVG(g.Price) AS AverageSpend, COUNT(DISTINCT g.Id) AS ProductVariety, COUNT(DISTINCT g.Food) AS FoodVariety, COUNT(DISTINCT g.Flavor) AS FlavorVariety FROM WeekdayFoodCustomers wfc JOIN receipts r ON wfc.Id = r.CustomerId JOIN items i ON r.ReceiptNumber = i.Receipt JOIN goods g ON i.Item = g.Id GROUP BY wfc.Id)

SELECT * FROM SpendingPatterns ORDER BY AverageSpend DESC LIMIT 10;
